import{_ as i,o as a,c as t,ag as n}from"./chunks/framework.BPmc_f4o.js";const c=JSON.parse('{"title":"Install on Linux","description":"Three ways to install Muxit on Ubuntu / Debian and what apt-packages it needs.","frontmatter":{"title":"Install on Linux","description":"Three ways to install Muxit on Ubuntu / Debian and what apt-packages it needs."},"headers":[],"relativePath":"guides/install-linux.md","filePath":"guides/install-linux.md"}'),e={name:"guides/install-linux.md"};function l(h,s,o,p,r,d){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="install-on-linux" tabindex="-1">Install on Linux <a class="header-anchor" href="#install-on-linux" aria-label="Permalink to &quot;Install on Linux&quot;">​</a></h1><p>Muxit ships a self-contained <code>linux-x64</code> tarball — the .NET runtime is included, so the host only needs a few system libraries for hardware features (camera streaming, system tray, serial-port access). Three installation paths are documented here, in order of convenience.</p><p>Tested on <strong>Ubuntu 22.04 LTS</strong> and <strong>Ubuntu 24.04 LTS</strong>. Should work on any glibc 2.31+ distro (Debian 11+, RHEL/AlmaLinux 8+); only the package names in step 2 differ on non-apt distros.</p><hr><h2 id="_1-one-liner-installer-recommended" tabindex="-1">1. One-liner installer (recommended) <a class="header-anchor" href="#_1-one-liner-installer-recommended" aria-label="Permalink to &quot;1. One-liner installer (recommended)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/muxit-io/muxit/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>What this does:</p><ol><li>Detects the distro (apt-only for now — clear error otherwise).</li><li>Installs <code>ffmpeg</code>, <code>libappindicator3-1</code>, <code>xdg-utils</code> via <code>sudo apt</code>. Asks for confirmation; skip with <code>--yes</code>.</li><li>Adds your user to the <code>dialout</code> group if not already a member (needed for <code>/dev/ttyUSB*</code> serial-port access).</li><li>Downloads the latest <code>muxit-linux-x64-v*.tar.gz</code> from GitHub Releases and verifies the SHA-256 against <code>checksums.txt</code>.</li><li>Extracts into <code>~/.local/share/muxit/</code>. An existing <code>workspace/</code> directory is preserved across reinstalls.</li><li>Symlinks <code>~/.local/bin/muxit</code> → installdir, so <code>muxit</code> lands on <code>$PATH</code>.</li><li>Prints how to launch.</li></ol><p><strong>Per-user install</strong>: nothing outside <code>~/.local/{share,bin}/</code> is touched on disk. Sudo is only used for the <code>apt install</code> and <code>usermod</code> steps.</p><h3 id="common-flags" tabindex="-1">Common flags <a class="header-anchor" href="#common-flags" aria-label="Permalink to &quot;Common flags&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Skip the apt-install step (re-install on a host where deps are already in place)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .../install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-apt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install somewhere else</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .../install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/muxit</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Don&#39;t prompt for anything</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .../install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Don&#39;t symlink ~/.local/bin/muxit (you launch by full path)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .../install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-symlink</span></span></code></pre></div><h3 id="re-running-the-installer" tabindex="-1">Re-running the installer <a class="header-anchor" href="#re-running-the-installer" aria-label="Permalink to &quot;Re-running the installer&quot;">​</a></h3><p>Re-running the same command upgrades to the latest release. The installer wipes and re-extracts only the shipped subdirs (<code>wwwroot/</code>, <code>runtimes/</code>, <code>Assets/</code>, <code>workspace-template/</code>) and the top-level binaries; <strong><code>workspace/</code> is preserved.</strong></p><hr><h2 id="_2-manual-install" tabindex="-1">2. Manual install <a class="header-anchor" href="#_2-manual-install" aria-label="Permalink to &quot;2. Manual install&quot;">​</a></h2><p>If you don&#39;t want to pipe a script into bash, do it by hand:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. System packages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ffmpeg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libappindicator3-1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xdg-utils</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Serial-port group (re-login or \`newgrp dialout\` after this)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dialout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $USER</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Download — set VERSION to the latest tag from https://github.com/muxit-io/muxit/releases</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VERSION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0.37.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/muxit</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/muxit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -LO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/muxit-io/muxit/releases/download/v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$VERSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/muxit-linux-x64-v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$VERSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -LO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/muxit-io/muxit/releases/download/v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$VERSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/checksums.txt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. Verify</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> muxit-linux-x64-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checksums.txt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5. Extract</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> muxit-linux-x64-v</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.tar.gz</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 6. (Optional) put it on PATH</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sfn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/muxit/muxit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/muxit</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 7. Launch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span></span></code></pre></div><hr><h2 id="_3-what-every-system-package-buys-you" tabindex="-1">3. What every system package buys you <a class="header-anchor" href="#_3-what-every-system-package-buys-you" aria-label="Permalink to &quot;3. What every system package buys you&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>What it enables</th><th>Without it</th></tr></thead><tbody><tr><td><code>ffmpeg</code></td><td>Onvif IP-camera RTSP streaming</td><td>Onvif <code>start</code> action throws <code>Failed to start ffmpeg subprocess</code></td></tr><tr><td><code>libappindicator3-1</code></td><td>System-tray icon (with View Logs / Restart / Quit)</td><td>Server runs normally; tray-icon stderr line on boot, no menubar entry</td></tr><tr><td><code>xdg-utils</code></td><td>Auto-open browser at startup</td><td>Server prints the URL; you open it yourself</td></tr><tr><td><code>dialout</code> group membership</td><td><code>/dev/ttyUSB*</code> and <code>/dev/ttyACM*</code> access</td><td>Serial drivers throw <code>EACCES</code> on init</td></tr></tbody></table><p>Muxit checks all of these at startup and prints non-fatal warnings under <strong>System dependencies</strong> in the boot banner — including the exact <code>apt</code> / <code>usermod</code> command to fix each one. So if you skip the installer entirely, the server itself tells you what&#39;s missing.</p><hr><h2 id="what-about-other-distros" tabindex="-1">What about other distros? <a class="header-anchor" href="#what-about-other-distros" aria-label="Permalink to &quot;What about other distros?&quot;">​</a></h2><p>The tarball is built against <strong>manylinux_2_28</strong> (glibc 2.28+) and should run on any reasonable modern distro. Only the package-manager commands differ:</p><ul><li><strong>Fedora / RHEL / AlmaLinux</strong> (<code>dnf</code>): <code>sudo dnf install ffmpeg-free libayatana-appindicator-gtk3 xdg-utils</code></li><li><strong>Arch / Manjaro</strong> (<code>pacman</code>): <code>sudo pacman -S ffmpeg libayatana-appindicator xdg-utils</code></li><li><strong>OpenSUSE</strong> (<code>zypper</code>): <code>sudo zypper install ffmpeg libappindicator3-1 xdg-utils</code></li></ul><p>The <code>install.sh</code> one-liner is apt-only for now; native dnf / pacman support is on the roadmap. Until then, the manual install (step 2 above) works on any distro — just substitute your distro&#39;s package manager for <code>apt install</code>.</p><hr><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/muxit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/muxit</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Optional: remove apt packages if you don&#39;t use them otherwise</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># sudo apt remove ffmpeg libappindicator3-1 xdg-utils</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Optional: leave dialout group</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># sudo gpasswd -d $USER dialout</span></span></code></pre></div><p>Your workspace is at <code>~/.local/share/muxit/workspace/</code>; back it up before deleting if it has device configs / scripts you want to keep.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>If something doesn&#39;t work, the <strong>&quot;View Logs&quot;</strong> entry in the system tray (or <code>http://localhost:8765/logs.html</code>) shows the live ringbuffer plus a <code>System dependencies</code> banner that calls out anything missing. See the <a href="/guides/troubleshooting.html#viewing-server-logs">troubleshooting guide</a> for more.</p><p>Common ones:</p><ul><li><strong>&quot;Failed to start <code>ffmpeg</code> subprocess&quot;</strong> when starting Onvif → install ffmpeg.</li><li><strong>&quot;Permission denied&quot; on <code>/dev/ttyUSB0</code></strong> → add user to <code>dialout</code> and re-login (or <code>newgrp dialout</code>).</li><li><strong>Tray icon not showing</strong> → install <code>libappindicator3-1</code> and restart muxit. The tray&#39;s native library links against the original appindicator soname (<code>libappindicator3.so.1</code>), not the Ayatana fork. On distros that dropped the package (Ubuntu 24.04+), install <code>libayatana-appindicator3-1</code> and symlink it: <code>sudo ln -s /usr/lib/x86_64-linux-gnu/libayatana-appindicator3.so.1 /usr/lib/x86_64-linux-gnu/libappindicator3.so.1</code>. Muxit&#39;s startup banner prints the exact soname the loader asked for.</li><li><strong>Browser doesn&#39;t auto-open</strong> → install <code>xdg-utils</code>, or just visit the printed URL yourself.</li></ul>`,35)])])}const g=i(e,[["render",l]]);export{c as __pageData,g as default};
